"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(arr, k):
    result = []
    deque = []
    for i in range(0, len(arr)):
        if (deque[0] == (i - k)):
            deque.pop(0)
        while ((len(deque) > 0) and (arr[deque[(-1)]] <= arr[i])):
            deque.pop()
        deque.append(i)
        if (i >= (k - 1)):
            result.append(arr[deque[0]])
    return result



print(unnamed_function([1, 3, -1, -3, 5, 3, 6, 7], 3))